\draw[->,line width=0.5pt] (-15,0)--(410,0) node[right] {$\theta$};
\draw[->,line width=0.5pt] (0,-3.1)--(0,3.15) node[above] {$y$};
\foreach \a in {0,90,180,270,360}{\draw[line width=0.4pt] (\a,-0.065)--(\a,0.065);\node[below=3pt] at (\a,0) {\special{dvisvgm:raw <g data-graph-text="tick">}$\a^\circ$\special{dvisvgm:raw </g>}};}
