\clip (0,-3) rectangle (360,3);
\draw[sineBlue,line width=0.8pt,domain=0:360,samples=181] plot (\x,{sin(\x)});
\draw[cosecantPurple,densely dashed,line width=0.8pt,domain=1:179,samples=240] plot (\x,{1/sin(\x)});
\draw[cosecantPurple,densely dashed,line width=0.8pt,domain=181:359,samples=240] plot (\x,{1/sin(\x)});
